/** Contract-based test harness for the compute entry point
  *
  * @param api_battery_evidence incoming data port
  * @param api_decision_disposition incoming data port
  */
pub fn testComputeCB(
  api_battery_evidence: Drone_Lifecycle_Governor::Battery_Evidence,
  api_decision_disposition: Drone_Lifecycle_Governor::Decision_Disposition) -> HarnessResult
{
  // Initialize the app
  crate::pilot_notice_derivation_process_pilot_notice_derivation_initialize();

  // [PutInPorts]: Set values on the input ports
  put_battery_evidence(api_battery_evidence);
  put_decision_disposition(api_decision_disposition);

  // [InvokeEntryPoint]: Invoke the entry point
  crate::pilot_notice_derivation_process_pilot_notice_derivation_timeTriggered();

  // [RetrieveOutState]: retrieve values of the output ports via get operations and GUMBO declared local state variable
  let api_pilot_notice = get_pilot_notice();

  // [CheckPost]: invoke the oracle function
  if !GUMBOX::compute_CEP_Post(api_battery_evidence, api_decision_disposition, api_pilot_notice) {
    return HarnessResult::FailedPostcondition(TestCaseError::Fail("Postcondition failed: incorrect output behavior".into()));
  }

  return HarnessResult::Passed
}

/** Contract-based test harness for the compute entry point
  */
pub fn testComputeCB_container(container: PreStateContainer) -> HarnessResult
{
  return testComputeCB(container.api_battery_evidence, container.api_decision_disposition)
}

